import React from "react";
import ReactDOM from "react-dom/client";
import "./index.css";
import BibleReader from "./BibleReader";

const root = ReactDOM.createRoot(document.getElementById("root"));

root.render(
    <React.StrictMode>
    <BibleReader />
    </React.StrictMode>
);

process.on('SIGINT', () => {
  console.log('Forcefully shutting down server...');
  process.exit(0); 
});
